//! Specification for assembling the generated files.

use super::*;

/// The files `generate` writes for an empty PostgreSQL catalog, by name.
fn generated(sqlc_version: &str, options: &str) -> Vec<(String, String)> {
    let request = plugin::GenerateRequest {
        settings: Some(plugin::Settings {
            engine: "postgresql".into(),
            ..Default::default()
        }),
        sqlc_version: sqlc_version.into(),
        plugin_options: options.as_bytes().to_vec(),
        ..Default::default()
    };
    (crate::generate(&request).unwrap().into_iter())
        .map(|file| (file.name, String::from_utf8(file.contents).unwrap()))
        .collect()
}

/// The header `generate` writes, read off `__init__.py`, which holds only it
/// on SQLAlchemy.
fn header_of(sqlc_version: &str, options: &str) -> String {
    let options = format!(r#"{{"backend": "sqlalchemy", "async": false{options}}}"#);
    generated(sqlc_version, &options).remove(0).1
}

#[test]
fn the_header_records_both_versions() {
    let version = env!("CARGO_PKG_VERSION");
    assert_eq!(
        header_of("v1.31.1", ""),
        format!(
            "# Code generated by sqlc-gen-python. DO NOT EDIT.\n\
             # versions:\n\
             #   sqlc-gen-python v{version}\n\
             #   sqlc v1.31.1\n"
        )
    );
}

#[test]
fn the_sqlc_line_is_left_out_when_asked_or_unknown() {
    let without = header_of("", "");
    assert!(!without.contains("sqlc v"), "{without}");
    assert_eq!(
        header_of("v1.31.1", r#", "omit_sqlc_version": true"#),
        without
    );
}

#[test]
fn the_package_defines_the_errors_of_a_one_where_the_library_has_none() {
    let init = |backend: &str, raises: bool| {
        let options =
            format!(r#"{{"backend": "{backend}", "async": false, "raise_on_none": {raises}}}"#);
        generated("", &options).remove(0).1
    };
    assert!(!init("sqlalchemy", true).contains("class"));
    for error in [
        "class NoRowError(LookupError):",
        "class MultipleRowsError(LookupError):",
    ] {
        assert!(init("psycopg", true).contains(error), "{error}");
    }
    // Without a row, `None`: only a second row raises.
    let none = init("psycopg", false);
    assert!(
        !none.contains("NoRowError") && none.contains("MultipleRowsError"),
        "{none}"
    );
}
